window.PROBLEM_SOURCES["react-05"] = {"id": "react-05", "language": "react", "stub": {"path": "react/practice_problems/problem_05_search_combobox.jsx", "source": "/**\n * =============================================================================\n * INTERVIEW PROBLEM 05: Accessible Async Search Combobox\n * Difficulty: Senior Software Engineer | Estimated time: 45 minutes\n * =============================================================================\n *\n * CONTEXT\n * -------\n * Build a command-style search control for a productivity SaaS. Accessibility\n * is a functional requirement: screen-reader and keyboard users must receive\n * the same state and selection behavior as pointer users.\n *\n * PROVIDED — DO NOT MODIFY\n * ------------------------\n * INITIAL_ITEMS, searchItems(query), and persistSelection(item) are supplied.\n * Tests intercept their HTTP requests, so do not replace these service seams.\n * Make defensive copies before storing provided arrays in mutable state.\n *\n * PART 1 — Accessible local combobox\n * -----------------------------------\n * Implement `useComboboxState(items, onSelect)` and use it in\n * `AccessibleSearchCombobox` to search/select from INITIAL_ITEMS.\n *\n * Requirements:\n *   - A visible <label> named \"Search workspace\" is associated to the input.\n *   - The input has role=\"combobox\", aria-autocomplete=\"list\",\n *     aria-controls, aria-expanded, and aria-activedescendant while active.\n *   - Results use role=\"listbox\" and role=\"option\"; the active option has\n *     aria-selected=\"true\" and a stable, readable DOM id derived from item.id.\n *   - ArrowDown/ArrowUp move and wrap; Home/End jump; Enter selects; Escape\n *     closes the popup without moving focus away from the input.\n *   - Clicking an option uses the same selection path as Enter.\n *\n * PART 2 — Debounced asynchronous item source\n * --------------------------------------------\n * Implement `useAsyncSearch(query, search, debounceMs = 300)`. Non-empty\n * queries call `search(query)` only after 300 ms. Expose loading, success,\n * empty, and error states. Suppress stale responses: only the newest request\n * may update visible results. Feed its items into the Part 1 hook and render\n * options through the same listbox/selection path—do not build a second list.\n *\n * PART 3 — Cache and optimistic recent selections\n * ------------------------------------------------\n * Implement `useSearchData(search, persist)`. It owns an instance-local query\n * cache and exposes a cached search function. It also exposes the selection\n * handler passed to Part 1: add a selection to the recent list immediately,\n * call persist, and remove that optimistic entry plus show an error on failure.\n * Cache arrays defensively. Repeating a successful query must not call search.\n *\n * COMPOSITION CHAIN\n * -----------------\n * `useComboboxState` drives selection -> `useAsyncSearch` replaces its items ->\n * `useSearchData` wraps fetch/persist and feeds the same selection handler.\n *\n * Required data-testid contract (supplements, never replaces, semantic ARIA):\n *   search-input, search-listbox, search-option, search-status, selected-item,\n *   recent-list, recent-item, recent-error\n *\n * Example:\n *   Type \"alp\" and advance fake time 300 ms: Alpha and Alpine appear.\n *   Press ArrowDown, then Enter: Alpha is selected immediately.\n *   If a slower earlier request for \"al\" resolves afterward, it is ignored.\n * =============================================================================\n */\n\nimport React from 'react'\n\nexport const INITIAL_ITEMS = [\n  { id: 'doc-alpha', label: 'Alpha', kind: 'Document' },\n  { id: 'doc-alpine', label: 'Alpine', kind: 'Document' },\n  { id: 'project-bravo', label: 'Bravo', kind: 'Project' },\n  { id: 'person-charlie', label: 'Charlie', kind: 'Person' },\n]\n\nexport async function searchItems(query) {\n  const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`)\n  if (!response.ok) throw new Error('Search failed')\n  return response.json()\n}\n\nexport async function persistSelection(item) {\n  const response = await fetch('/api/recent-selections', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ itemId: item.id }),\n  })\n  if (!response.ok) throw new Error('Could not save recent selection')\n}\n\n// PART 1\nexport function useComboboxState(items, onSelect) {\n  throw new Error('Not implemented: Part 1 useComboboxState')\n}\n\n// PART 2\nexport function useAsyncSearch(query, search, debounceMs = 300) {\n  throw new Error('Not implemented: Part 2 useAsyncSearch')\n}\n\n// PART 3\nexport function useSearchData(search, persist) {\n  throw new Error('Not implemented: Part 3 useSearchData')\n}\n\nexport function AccessibleSearchCombobox({\n  search = searchItems,\n  persist = persistSelection,\n}) {\n  throw new Error('Not implemented: compose Parts 1–3')\n}\n\nexport default function App() {\n  return <AccessibleSearchCombobox />\n}\n"}, "test": {"path": "react/tests/test_problem_05_search_combobox.spec.js", "source": "import { test as base, expect } from '@playwright/test'\n\nconst ALPHA_RESULTS = [\n  { id: 'result-alpha', label: 'Alpha', kind: 'Document' },\n  { id: 'result-alpine', label: 'Alpine', kind: 'Project' },\n]\n\nconst test = base.extend({\n  freshPage: async ({ page }, use) => {\n    await page.route('**/api/recent-selections', route => route.fulfill({ status: 204 }))\n    await page.goto('/')\n    await use(page)\n  },\n  seededPage: async ({ page }, use) => {\n    await page.route('**/api/search**', route => route.fulfill({ json: ALPHA_RESULTS.map(item => ({ ...item })) }))\n    await page.route('**/api/recent-selections', route => route.fulfill({ status: 204 }))\n    await page.goto('/')\n    await use(page)\n  },\n})\n\ntest.describe('Part 1 — ARIA roles, keyboard navigation, and focus management', () => {\n  test('associates a visible label and exposes the combobox relationship', async ({ freshPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await expect(input).toBeVisible()\n    await expect(input).toHaveAttribute('aria-autocomplete', 'list')\n    await input.focus()\n    const listbox = page.getByRole('listbox', { name: 'Search results' })\n    await expect(listbox).toBeVisible()\n    await expect(input).toHaveAttribute('aria-controls', await listbox.getAttribute('id'))\n    await expect(input).toHaveAttribute('aria-expanded', 'true')\n  })\n\n  test('manages active descendant and selects with ArrowDown and Enter', async ({ freshPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.focus()\n    await input.press('ArrowDown')\n    const alpha = page.getByRole('option', { name: /Alpha Document/ })\n    await expect(alpha).toHaveAttribute('aria-selected', 'true')\n    await expect(input).toHaveAttribute('aria-activedescendant', await alpha.getAttribute('id'))\n    await input.press('Enter')\n    await expect(page.getByTestId('selected-item')).toHaveText('Alpha')\n    await expect(input).toBeFocused()\n  })\n\n  test('supports wrapping plus Home and End navigation', async ({ freshPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.focus()\n    await input.press('ArrowUp')\n    await expect(page.getByRole('option', { name: /Charlie Person/ })).toHaveAttribute('aria-selected', 'true')\n    await input.press('Home')\n    await expect(page.getByRole('option', { name: /Alpha Document/ })).toHaveAttribute('aria-selected', 'true')\n    await input.press('End')\n    await expect(page.getByRole('option', { name: /Charlie Person/ })).toHaveAttribute('aria-selected', 'true')\n  })\n\n  test('Escape closes the popup and preserves input focus', async ({ freshPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.focus()\n    await input.press('ArrowDown')\n    await input.press('Escape')\n    await expect(input).toHaveAttribute('aria-expanded', 'false')\n    await expect(page.getByRole('listbox', { name: 'Search results' })).toBeHidden()\n    await expect(input).toBeFocused()\n    await expect(input).not.toHaveAttribute('aria-activedescendant', /.+/)\n  })\n\n  test('clicking an option uses the same selection result', async ({ freshPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.focus()\n    await page.getByRole('option', { name: /Bravo Project/ }).click()\n    await expect(page.getByTestId('selected-item')).toHaveText('Bravo')\n    await expect(input).toHaveAttribute('aria-expanded', 'false')\n  })\n})\n\ntest.describe('Part 2 — debounce, errors, and stale-response suppression', () => {\n  test.beforeEach(async ({ page }) => { await page.clock.install() })\n\n  test('waits exactly 300 ms before searching and renders loading/results', async ({ seededPage: page }) => {\n    let requests = 0\n    let pendingRoute\n    await page.unroute('**/api/search**')\n    await page.route('**/api/search**', route => {\n      requests += 1\n      pendingRoute = route\n    })\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('alp')\n    await page.clock.fastForward(299)\n    expect(requests).toBe(0)\n    await page.clock.fastForward(1)\n    await expect(page.getByTestId('search-status')).toHaveText(/loading/i)\n    await pendingRoute.fulfill({ json: ALPHA_RESULTS.map(item => ({ ...item })) })\n    await expect(page.getByRole('option')).toHaveCount(2)\n    expect(requests).toBe(1)\n  })\n\n  test('renders deterministic empty and network error states', async ({ page }) => {\n    await page.route('**/api/search**', async route => {\n      const query = new URL(route.request().url()).searchParams.get('q')\n      if (query === 'error-unique') await route.fulfill({ status: 503 })\n      else await route.fulfill({ json: [] })\n    })\n    await page.goto('/')\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('empty-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByTestId('search-status')).toHaveText(/no results/i)\n    await input.fill('error-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByTestId('search-status')).toHaveText(/search failed/i)\n  })\n\n  test('ignores a slower earlier response that arrives last', async ({ page }) => {\n    const pending = new Map()\n    await page.route('**/api/search**', route => {\n      pending.set(new URL(route.request().url()).searchParams.get('q'), route)\n    })\n    await page.goto('/')\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('al')\n    await page.clock.fastForward(300)\n    await expect.poll(() => pending.has('al')).toBe(true)\n    await input.fill('alp')\n    await page.clock.fastForward(300)\n    await expect.poll(() => pending.has('alp')).toBe(true)\n    await pending.get('alp').fulfill({ json: ALPHA_RESULTS.map(item => ({ ...item })) })\n    await expect(page.getByRole('option')).toHaveCount(2)\n    await pending.get('al').fulfill({ json: [{ id: 'stale-albatross', label: 'Albatross', kind: 'Document' }] })\n    await expect(page.getByRole('option', { name: /Alpha Document/ })).toBeVisible()\n    await expect(page.getByRole('option', { name: /Albatross/ })).toHaveCount(0)\n  })\n})\n\ntest.describe('Part 3 — cache and optimistic recent selections', () => {\n  test.beforeEach(async ({ page }) => { await page.clock.install() })\n\n  test('serves a repeated successful query from the instance cache', async ({ page }) => {\n    let requests = 0\n    await page.route('**/api/search**', async route => {\n      requests += 1\n      await route.fulfill({ json: ALPHA_RESULTS.map(item => ({ ...item })) })\n    })\n    await page.route('**/api/recent-selections', route => route.fulfill({ status: 204 }))\n    await page.goto('/')\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('cache-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByRole('option')).toHaveCount(2)\n    await input.fill('different-unique')\n    await page.clock.fastForward(300)\n    await expect.poll(() => requests).toBe(2)\n    await input.fill('cache-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByRole('option')).toHaveCount(2)\n    expect(requests).toBe(2)\n  })\n\n  test('shows a recent selection optimistically and keeps it on success', async ({ seededPage: page }) => {\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('optimistic-success-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByRole('option')).toHaveCount(2)\n    await input.press('ArrowDown')\n    await input.press('Enter')\n    await expect(page.getByTestId('recent-item')).toHaveText('Alpha')\n    await expect(page.getByTestId('recent-error')).toHaveCount(0)\n  })\n\n  test('rolls back the optimistic recent item when persistence fails', async ({ page }) => {\n    let rejectPersist\n    await page.route('**/api/search**', route => route.fulfill({ json: ALPHA_RESULTS.map(item => ({ ...item })) }))\n    await page.route('**/api/recent-selections', route => { rejectPersist = route })\n    await page.goto('/')\n    const input = page.getByRole('combobox', { name: 'Search workspace' })\n    await input.fill('rollback-unique')\n    await page.clock.fastForward(300)\n    await expect(page.getByRole('option')).toHaveCount(2)\n    await input.press('ArrowDown')\n    await input.press('Enter')\n    await expect(page.getByTestId('recent-item')).toHaveText('Alpha')\n    await expect.poll(() => Boolean(rejectPersist)).toBe(true)\n    await rejectPersist.fulfill({ status: 500 })\n    await expect(page.getByTestId('recent-item')).toHaveCount(0)\n    await expect(page.getByTestId('recent-error')).toHaveText(/could not save/i)\n  })\n})\n"}, "parts": [{"part": 1, "source": " * PART 1 — Accessible local combobox\n * -----------------------------------\n * Implement `useComboboxState(items, onSelect)` and use it in\n * `AccessibleSearchCombobox` to search/select from INITIAL_ITEMS.\n *\n * Requirements:\n *   - A visible <label> named \"Search workspace\" is associated to the input.\n *   - The input has role=\"combobox\", aria-autocomplete=\"list\",\n *     aria-controls, aria-expanded, and aria-activedescendant while active.\n *   - Results use role=\"listbox\" and role=\"option\"; the active option has\n *     aria-selected=\"true\" and a stable, readable DOM id derived from item.id.\n *   - ArrowDown/ArrowUp move and wrap; Home/End jump; Enter selects; Escape\n *     closes the popup without moving focus away from the input.\n *   - Clicking an option uses the same selection path as Enter.\n *\n *\n"}, {"part": 2, "source": " * PART 2 — Debounced asynchronous item source\n * --------------------------------------------\n * Implement `useAsyncSearch(query, search, debounceMs = 300)`. Non-empty\n * queries call `search(query)` only after 300 ms. Expose loading, success,\n * empty, and error states. Suppress stale responses: only the newest request\n * may update visible results. Feed its items into the Part 1 hook and render\n * options through the same listbox/selection path—do not build a second list.\n *\n *\n"}, {"part": 3, "source": " * PART 3 — Cache and optimistic recent selections\n * ------------------------------------------------\n * Implement `useSearchData(search, persist)`. It owns an instance-local query\n * cache and exposes a cached search function. It also exposes the selection\n * handler passed to Part 1: add a selection to the recent list immediately,\n * call persist, and remove that optimistic entry plus show an error on failure.\n * Cache arrays defensively. Repeating a successful query must not call search.\n *\n * COMPOSITION CHAIN\n * -----------------\n * `useComboboxState` drives selection -> `useAsyncSearch` replaces its items ->\n * `useSearchData` wraps fetch/persist and feeds the same selection handler.\n *\n * Required data-testid contract (supplements, never replaces, semantic ARIA):\n *   search-input, search-listbox, search-option, search-status, selected-item,\n *   recent-list, recent-item, recent-error\n *\n * Example:\n *   Type \"alp\" and advance fake time 300 ms: Alpha and Alpine appear.\n *   Press ArrowDown, then Enter: Alpha is selected immediately.\n *   If a slower earlier request for \"al\" resolves afterward, it is ignored.\n"}], "implementationSurface": "import React from 'react'\n\nexport const INITIAL_ITEMS = [\n  { id: 'doc-alpha', label: 'Alpha', kind: 'Document' },\n  { id: 'doc-alpine', label: 'Alpine', kind: 'Document' },\n  { id: 'project-bravo', label: 'Bravo', kind: 'Project' },\n  { id: 'person-charlie', label: 'Charlie', kind: 'Person' },\n]\n\nexport async function searchItems(query) {\n  const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`)\n  if (!response.ok) throw new Error('Search failed')\n  return response.json()\n}\n\nexport async function persistSelection(item) {\n  const response = await fetch('/api/recent-selections', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ itemId: item.id }),\n  })\n  if (!response.ok) throw new Error('Could not save recent selection')\n}\n\n// PART 1\nexport function useComboboxState(items, onSelect) {\n  throw new Error('Not implemented: Part 1 useComboboxState')\n}\n\n// PART 2\nexport function useAsyncSearch(query, search, debounceMs = 300) {\n  throw new Error('Not implemented: Part 2 useAsyncSearch')\n}\n\n// PART 3\nexport function useSearchData(search, persist) {\n  throw new Error('Not implemented: Part 3 useSearchData')\n}\n\nexport function AccessibleSearchCombobox({\n  search = searchItems,\n  persist = persistSelection,\n}) {\n  throw new Error('Not implemented: compose Parts 1–3')\n}\n\nexport default function App() {\n  return <AccessibleSearchCombobox />\n}\n"};
